import{_ as l,o as s,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Crimson/Seastar OSD Meeting 2018-12-04","description":"","frontmatter":{"title":"Crimson/Seastar OSD Meeting 2018-12-04","date":"2018-12-04T00:00:00.000Z","updated":"2018-12-06T00:00:00.000Z","tags":["Ceph","Ceph分布式存储","OSD","Crimson项目","同步问题"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Crimson_Seastar_OSD_Meeting_2018-12-04.md","filePath":"posts/2018/Crimson_Seastar_OSD_Meeting_2018-12-04.md","lastUpdated":1780460162000}'),r={name:"posts/2018/Crimson_Seastar_OSD_Meeting_2018-12-04.md"};function n(o,i,a,p,u,_){return s(),e("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年12月4日</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>： Ceph分布式存储系统开发讨论</p><p><strong>会议内容</strong>：</p><p><strong>1. 网络连接问题</strong></p><ul><li>由于网络连接问题，部分参会人员无法正常参与会议。Jim今日无法参加会议，因他今日不在办公室。</li></ul><p><strong>2. 功能开发与优化</strong></p><ul><li>讨论了Ceph中“finish”功能开发的进展，包括： <ul><li>修改代码以注册Kovac观察者。</li><li>修复OS中的一些错误。</li><li>优化代码以在POSIX环境下运行。</li></ul></li><li>讨论了如何解决在跨不同分支代码合并时出现的兼容性问题。</li></ul><p><strong>3. crimson项目</strong></p><ul><li>讨论了crimson项目中的同步问题，包括： <ul><li>crimson需要使用with sister，而synchronous messenger不需要。</li><li>在同一文件中同时存在两种类型的messenger，导致冲突。</li><li>探讨了如何将sharded crimson messenger分配到不同的shard。</li></ul></li></ul><p><strong>4. 其他</strong></p><ul><li>讨论了以下内容： <ul><li>使用boost intrusive库时遇到的问题。</li><li>代码合规性检查。</li><li>复制bucket在sister OSD上的实现。</li></ul></li></ul><p><strong>决定事项</strong>：</p><ul><li>参会人员决定： <ul><li>继续推进finish功能的开发。</li><li>解决crimson项目中的同步问题。</li><li>修复boost intrusive库相关的问题。</li><li>完成代码合规性检查。</li></ul></li></ul><p><strong>后续行动计划</strong>：</p><ul><li>参会人员将： <ul><li>继续跟进finish功能的开发。</li><li>解决crimson项目中的同步问题。</li><li>修复boost intrusive库相关的问题。</li><li>完成代码合规性检查。</li></ul></li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了以下计算机科学/ceph相关领域英文关键词： <ul><li>finish</li><li>Kovac observer</li><li>POSIX</li><li>crimson</li><li>sharded crimson messenger</li><li>boost intrusive</li><li>compliance</li><li>replicated bucket</li></ul></li></ul>',19)])])}const m=l(r,[["render",n]]);export{c as __pageData,m as default};
